def audit_installed_packages(installed_map: dict[str, str], required_map: dict[str, str]) -> list[str]:
    issues = []
    for pkg, min_ver in required_map.items():
        if pkg not in installed_map:
            issues.append(f'MISSING: {pkg}')
        else:
            cur_ver = installed_map[pkg]
            cur_tuple = tuple(map(int, cur_ver.split('.')))
            req_tuple = tuple(map(int, min_ver.split('.')))
            if cur_tuple < req_tuple:
                issues.append(f'OUTDATED: {pkg} ({cur_ver} < {min_ver})')
    return issues

