# 演示通过实现 __eq__ 与 __lt__ 赋予对象直接 sorted() 的能力
class PriorityTask:
    def __init__(self, name: str, priority: int) -> None:
        self.name = name
        self.priority = priority

    def __repr__(self) -> str:
        return f"{self.name}(P{self.priority})"

    def __eq__(self, other) -> bool:
        if not isinstance(other, PriorityTask):
            return False
        return self.priority == other.priority

    def __lt__(self, other) -> bool:
        if not isinstance(other, PriorityTask):
            return NotImplemented
        # 优先级数字越小越优先
        return self.priority < other.priority

tasks = [PriorityTask("发送邮件", 3), PriorityTask("数据库备份", 1), PriorityTask("安全审计", 2)]
print("原始任务列表:", tasks)
# 原生 sorted 会自动利用 __lt__ 进行快速排序！
print("排序后队列:", sorted(tasks))

