import json
from typing import Any

class SerializerFactory:
    _registry = {
        'json': lambda d: json.dumps(d),
        'text': lambda d: str(d)
    }

    @classmethod
    def register(cls, format_name: str, serializer_func):
        cls._registry[format_name.lower()] = serializer_func

    @classmethod
    def serialize(cls, format_name: str, data: Any) -> str:
        fmt = format_name.lower()
        if fmt not in cls._registry:
            raise ValueError(f'未知序列化格式: {format_name}')
        return cls._registry[fmt](data)

