# 演示通过 contextmanager 实现数据更新事务失败自动回滚
from contextlib import contextmanager

state_store = {"balance": 1000.0}

@contextmanager
def account_transaction(store):
    snapshot = store["balance"]
    print(f"[事务开始] 备份原始余额快照: {snapshot}")
    try:
        yield store
        print("[事务提交] 操作全部成功！")
    except Exception as e:
        print(f"[事务回滚] 发生异常: {e}，正在还原余额...")
        store["balance"] = snapshot
        raise  # 重新抛出

try:
    with account_transaction(state_store) as s:
        s["balance"] -= 200.0
        raise RuntimeError("网络中断，扣款未确认！")
except RuntimeError:
    pass

print("最终账户余额 (已被安全还原):", state_store["balance"])

