from contextlib import contextmanager

@contextmanager
def temporary_env_override(env_dict: dict, key: str, temp_value: str):
    has_key = key in env_dict
    old_val = env_dict.get(key)
    env_dict[key] = temp_value
    try:
        yield
    finally:
        if has_key:
            env_dict[key] = old_val
        else:
            env_dict.pop(key, None)

