# 演示工业级通用执行耗时打点装饰器
import functools
import time

def time_audit(threshold_ms: float = 5.0):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            t0 = time.perf_counter()
            res = fn(*args, **kwargs)
            cost_ms = (time.perf_counter() - t0) * 1000
            if cost_ms >= threshold_ms:
                print(f"[性能告警] 函数 {fn.__name__} 耗时偏高: {cost_ms:.2f} ms >= 阈值 {threshold_ms} ms")
            return res
        return wrapper
    return decorator

@time_audit(threshold_ms=1.0)
def heavy_task():
    return sum(i for i in range(200000))

print("任务结果:", heavy_task())

