import functools
from typing import Callable

def limit_calls(max_calls: int):
    def decorator(func: Callable) -> Callable:
        calls = 0
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal calls
            if calls >= max_calls:
                raise RuntimeError('超出最大调用次数限制')
            calls += 1
            return func(*args, **kwargs)
        return wrapper
    return decorator

exercises.tests:
@limit_calls(max_calls=2)
def ping():
    return 'pong'

assert ping.__name__ == 'ping'
assert ping() == 'pong'
assert ping() == 'pong'
try:
    ping()
    assert False, '未如期拦截超额调用'
except RuntimeError as e:
    assert '超出最大调用次数限制' in str(e)

