def run_pipeline(records: list[dict], threshold: float) -> dict:
    valid_count = 0
    total_sum = 0.0
    high_count = 0
    for r in records:
        try:
            if r.get('status') != 'SUCCESS':
                continue
            amt = float(r.get('amount', 0))
            if amt <= 0:
                continue
            valid_count += 1
            total_sum += amt
            if amt > threshold:
                high_count += 1
        except (ValueError, TypeError):
            continue
    return {
        'valid_count': valid_count,
        'total_sum': round(total_sum, 2),
        'high_count': high_count
    }

